namespace BARANG.Backoffice.Components.Help;

// Spanish help content for every HelpCatalog topic, keyed by node Id.
// Falls back to English when an id is missing (never Persian).
public static class SpanishHelp
{
    private const string ListIntro = "• Añadir, editar y activar/desactivar los elementos de esta lista desde esta misma página\n• Búsqueda rápida entre los elementos y títulos en cuatro idiomas (fa/ar/en/es)\n";

    public sealed record Topic(string Name, string Purpose, string Features);

    public static string Name(string id, string fallback) => Entries.TryGetValue(id, out Topic? t) ? t.Name : fallback;
    public static string Purpose(string id, string fallback) => Entries.TryGetValue(id, out Topic? t) ? t.Purpose : fallback;
    public static string Features(string id, string fallback) => Entries.TryGetValue(id, out Topic? t) ? t.Features : fallback;

    private static Topic T(string name, string purpose, string features) => new(name, purpose, features);
    private static Topic Leaf(string name, string purpose, string usage) => T(name, purpose, ListIntro + usage);

    private static readonly System.Collections.Generic.Dictionary<string, Topic> Entries = new()
    {
        ["home"] = T("Inicio", "La página de aterrizaje diaria de cada usuario: todo lo que espera tu acción, la actividad reciente, las notificaciones nuevas y los accesos a datos maestros en un solo lugar.",
            "• Resumen de «elementos que esperan tu acción» con enlaces directos a cada caso\n• Sección «mis tareas» y salto de un clic a la bandeja de trabajo\n• Acceso rápido a las seis secciones de datos maestros\n• «Mi actividad reciente» con la hora exacta de cada registro\n• «Notificaciones recientes» enlazadas a sus páginas\n• Fecha del calendario vigente y empresa actual"),
        ["master"] = T("Datos maestros", "El repositorio central de definiciones de la organización: cada tipo, código y clasificación que se selecciona en pedidos, precios, inventario, producción e informes se define aquí. La calidad de los datos maestros afecta directamente a los cálculos e informes. Cada dominio muestra su lista de tipos en la barra lateral y cada tipo se gestiona desde esa misma página.",
            "• 14 dominios de datos maestros: compartidos, clientes, proveedores, productos, banco de diseños, pedidos, precios, finanzas, inventario, equipos, producción, calidad, logística y bandeja de trabajo\n• Elige un dominio en la barra lateral y gestiona sus tipos en la misma página\n• Añadir, editar y activar/desactivar cada elemento\n• Registra el título de cada elemento en cuatro idiomas\n• Búsqueda rápida dentro de cada lista"),
        ["system"] = T("Gestión del sistema", "Gestión de la estructura organizativa, las personas, los activos y la seguridad de acceso. Todo lo que decide «quién, dónde, con qué acceso» se gestiona aquí, normalmente limitado a roles de administración.",
            "• Estructura organizativa, personas, proveedores, equipos, turnos y productos\n• Gestión de usuarios, roles y permisos\n• Configuración del flujo de trabajo\n• Acceso basado en roles (menús y operaciones de cada usuario)"),
        ["customers"] = T("Clientes", "El registro completo de clientes de la empresa, el corazón del sistema: cada pedido, factura y envío se vincula a un cliente. Los clientes se registran como persona física o jurídica y cada uno tiene un perfil completo: contactos (con rol), direcciones (con tipo), cuentas bancarias, estado financiero y el grupo/clasificación que determina el precio.",
            "• Registrar clientes individuales o corporativos con formularios específicos por tipo\n• Gestionar contactos (con roles), direcciones (con tipos) y cuentas bancarias\n• Buscar y filtrar clientes por nombre/código/grupo\n• Ver el historial por cliente: pedidos, facturas y estado financiero\n• Editar y archivar clientes sin perder el historial\n• Usar clientes como parte del pedido en todos los módulos"),
        ["design-bank"] = T("Banco de diseños", "El repositorio central de todos los diseños de impresión: cada diseño tiene un código único, su archivo original y varias versiones (cada revisión genera una nueva versión conservando el historial). Los diseños se buscan mediante categorías multilingües, etiquetas y clasificaciones; el sistema genera automáticamente miniatura y vista previa por versión, y al hacer un pedido el diseño se elige aquí respetando su licencia de uso.",
            "• Crear un diseño con código único, título, categoría y descripción\n• Subir archivos de diseño con validación de tipo y firma\n• Versionado: cada revisión = una versión nueva con historial\n• Miniatura y vista previa web automáticas por versión\n• Búsqueda textual y búsqueda conceptual entre diseños\n• Filtro por categoría multilingüe y estado\n• Paginación sobre más de 595 diseños con navegación\n• Visor de imagen grande e historial de versiones\n• Archivar/activar diseños; selección al pedir respetando licencias"),
        ["orders"] = T("Pedidos", "El ciclo de vida completo del pedido de impresión desde la solicitud del cliente hasta la entrega: crear borrador, elegir cliente, añadir líneas (producto + diseño del banco + operaciones de impresión con método/ubicación/tamaño), precio en vivo calculado por el motor, envío por el flujo de aprobación y paso a producción, control de calidad y logística. Cada cambio queda versionado, registrado y auditable.",
            "• Crear un pedido nuevo (borrador) con cliente y sucursal\n• Añadir/editar/eliminar líneas eligiendo producto y diseño\n• Elegir un diseño del banco de diseños por línea\n• Añadir operaciones de impresión (método/ubicación/tamaño) por línea\n• Cálculo de precio en vivo con tarifas, descuentos e impuestos\n• Enviar el pedido por el flujo de aprobación\n• Buscar y filtrar pedidos por estado/cliente/fecha\n• Vista completa de detalles, historial de cambios y versión de concurrencia\n• Continuar el recorrido: producción, control de calidad y envío"),
        ["cartable"] = T("Bandeja de trabajo", "La mesa de trabajo diaria de cada usuario: todas las acciones que le esperan — aprobar pedidos, confirmar precios, inspecciones, aprobar envíos — llegan automáticamente desde el flujo de trabajo. El usuario abre cada caso, actúa (aprobar/rechazar/reenviar) y el sistema aplica el SLA de cada tarea, escalando lo vencido a la dirección.",
            "• Mostrar «elementos que esperan acción» con prioridad y vencimiento\n• Abrir cada caso y ver el detalle completo del pedido\n• Actuar (aprobar/rechazar/suspender) con comentarios\n• Pestaña «mis derivaciones» para seguimientos delegados\n• Filtrar por tipo de tarea y estado\n• Control de SLA con avisos de vencimiento próximo"),
        ["pricing"] = T("Precios", "El motor de precios de pedidos: en lugar de presupuestos manuales, aquí se definen las tarifas base (por producto/operación de impresión), las reglas de descuento (por grupo de cliente o cantidad), los impuestos y los recargos. Al registrar el pedido estas reglas se aplican de forma automática y transparente, y cada componente del precio queda preservado en el historial.",
            "• Definir/editar tarifas base por producto/operación\n• Reglas de descuento por grupo de cliente y cantidad\n• Configurar tasas de impuesto y su aplicabilidad\n• Simular el precio de un pedido antes del envío definitivo\n• Historial completo de los componentes de precio de cada pedido\n• Integración con grupos de clientes para precios escalonados"),
        ["inventory"] = T("Inventario y compras", "Gestión completa de almacén y compras: existencias por artículo y almacén, reservas para pedidos en curso, detección de faltantes de material antes de producir, solicitudes de compra, aprobación y conversión en órdenes de compra a proveedores, recepción de mercancía y ajustes de inventario con motivo. Así la producción nunca se detiene por falta de materiales.",
            "• Ver existencias por artículo y almacén\n• Reservar existencias para pedidos en curso\n• Detectar y gestionar faltantes con alertas\n• Crear solicitudes de compra mediante el flujo de aprobación\n• Convertir solicitudes aprobadas en órdenes de compra\n• Registrar recepciones con actualización automática de stock\n• Ajustes de inventario con motivo e historial completo\n• Informes de consumo y mermas"),
        ["production"] = T("Producción", "El taller de impresión y prensa: los pedidos aprobados generan automáticamente tareas de producción (una por línea/operación de impresión). El planificador asigna máquina, turno y operario; el operario registra inicio, suspensión y finalización, capturando el tiempo real de ejecución. Al completar cada tarea de impresión/prensa se abre automáticamente una inspección de calidad, de modo que el flujo producción→calidad continúa sin pasos manuales.",
            "• Cola de producción con KPIs en cola/en curso/suspendida\n• Iniciar, suspender (con motivo) y completar cada tarea\n• Asignar máquina, turno y operario a cada tarea\n• Registrar el tiempo real de ejecución para medir rendimiento\n• Gráfico de dónut interactivo con la distribución de estados\n• Filtrar por estado, tipo de tarea y prioridad\n• Interruptor «mis tareas» para ver solo las del usuario\n• Inspección de calidad automática tras completar impresión/prensa"),
        ["quality"] = T("Control de calidad", "La inspección de cada tarea de producción: el inspector completa la lista de criterios, registra defectos con tipo/cantidad/gravedad y decide: aceptar, rechazar, suspender para revisión o emitir una solicitud de reproducción que vuelve a la cola de producción como tarea nueva referida a la original. Las estadísticas de merma y el informe Pareto de defectos se construyen con estos registros, guiando la mejora de procesos.",
            "• Lista de inspecciones con filtros de estado y resultado\n• Completar la lista de criterios de calidad de cada tarea\n• Registrar defectos con tipo, cantidad y gravedad\n• Decisiones: aceptar / rechazar / suspender / revisar\n• Emitir solicitudes de reproducción con las cantidades necesarias\n• Ver el historial de inspecciones y decisiones\n• Gráfico Pareto de defectos para análisis de causa raíz\n• Integrado con producción: inspección automática al completar la tarea"),
        ["logistics"] = T("Logística", "La última milla: los artículos producidos y aprobados se embalan (un bulto = los artículos de un pedido), se entregan al almacén de envío, se crea el envío con código de seguimiento y transportista, y se hace seguimiento hasta la entrega correcta o la devolución. En cada paso, el estado del pedido se actualiza para el cliente y el equipo de ventas.",
            "• Crear bultos con los artículos listos para enviar\n• Entregar bultos al almacén de envío registrando el receptor\n• Crear envíos eligiendo transportista y código de seguimiento\n• Ciclo del envío: listo → despachado → en tránsito → entregado/fallido → devuelto\n• Gráfico de distribución de estados de envío\n• Seguimiento del envío para clientes y equipo de ventas\n• Filtrar envíos por estado y transportista"),
        ["notifications"] = T("Notificaciones", "La bandeja de mensajes del sistema: los eventos clave (nuevo pedido registrado, precio pendiente de aprobación, envío despachado, tarea vencida) llegan automáticamente. El usuario gestiona el estado leído/sin leer, pulsa una notificación y salta directo a la página relacionada. La campana superior muestra en vivo el contador de no leídas.",
            "• Lista de notificaciones separada en leídas/no leídas\n• Insignia con el número de no leídas en la campana superior\n• Pulsar una notificación → ir directo a la página relacionada\n• Marcar manualmente como leída/no leída\n• Agrupación por tipo de evento\n• Historial de notificaciones para revisión posterior"),
        ["management"] = T("Panel de gestión", "Una foto en vivo de la salud del negocio para la dirección: pedidos por estado, ingresos, tendencia de producción, rendimiento de operarios, estados de envío y mermas de calidad, todo leído en tiempo real desde los datos reales de los módulos. Pensado para las reuniones semanales de dirección y decisiones rápidas.",
            "• Tarjetas KPI con recuentos y proporciones por estado\n• Gráficos de desglose de pedidos, producción y envíos\n• Rendimiento comparado de operarios y equipos\n• Datos en vivo de todos los módulos (sin carga manual)\n• Adecuado para reuniones de dirección e informes rápidos"),
